const cfg = $('Config').first().json;
const cronJobList = $('Get CronJobs').first().json;
const jobList = $('Get Jobs').first().json;

const watchedNames = String(cfg.cronJobNames || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

const missedGraceMinutes = Number(cfg.missedGraceMinutes || 30);
const jobLookbackHours = Number(cfg.jobLookbackHours || 24);
const now = Date.now();
const lookbackCutoff = now - jobLookbackHours * 60 * 60 * 1000;

function parseCronFields(schedule) {
  if (!schedule || typeof schedule !== 'string') return null;
  const parts = schedule.trim().split(/\s+/);
  if (parts.length < 5) return null;
  return {
    minute: parts[0],
    hour: parts[1],
    dayOfMonth: parts[2],
    month: parts[3],
    dayOfWeek: parts[4],
  };
}

// Rough expected interval for common schedules. Used only as a missed-run heuristic.
function estimateIntervalMinutes(schedule) {
  const fields = parseCronFields(schedule);
  if (!fields) return 60;

  if (/^\*\/(\d+)$/.test(fields.minute)) {
    return Number(fields.minute.slice(2));
  }
  if (fields.minute !== '*' && fields.hour === '*') return 60;
  if (fields.minute !== '*' && fields.hour !== '*' && fields.dayOfMonth === '*' && fields.month === '*' && (fields.dayOfWeek === '*' || fields.dayOfWeek === '?')) {
    return 24 * 60;
  }
  if (fields.dayOfWeek !== '*' && fields.dayOfWeek !== '?') return 7 * 24 * 60;
  return 60;
}

function ownerCronJobName(job) {
  const owners = job.metadata?.ownerReferences || [];
  const owner = owners.find((o) => o.kind === 'CronJob');
  if (owner?.name) return owner.name;

  const labels = job.metadata?.labels || {};
  return (
    labels['batch.kubernetes.io/cron-job-name'] ||
    labels['cronjob.kubernetes.io/cron-job-name'] ||
    labels['job-name']?.replace(/-\d{8,}$/, '') ||
    null
  );
}

function jobOutcome(job) {
  const status = job.status || {};
  const conditions = status.conditions || [];
  const complete = conditions.find((c) => c.type === 'Complete' && c.status === 'True');
  const failed = conditions.find((c) => c.type === 'Failed' && c.status === 'True');

  if (failed || Number(status.failed || 0) > 0) {
    return {
      state: 'failed',
      reason: failed?.reason || 'JobFailed',
      message: failed?.message || `failed pods=${status.failed}`,
      finishedAt: failed?.lastTransitionTime || job.metadata?.creationTimestamp,
    };
  }

  if (complete || Number(status.succeeded || 0) > 0) {
    return {
      state: 'succeeded',
      reason: complete?.reason || 'Complete',
      message: complete?.message || 'Job completed successfully',
      finishedAt: complete?.lastTransitionTime || job.metadata?.creationTimestamp,
    };
  }

  return {
    state: 'running_or_pending',
    reason: 'NotFinished',
    message: `active=${status.active || 0} succeeded=${status.succeeded || 0} failed=${status.failed || 0}`,
    finishedAt: null,
  };
}

const allCronJobs = cronJobList.items || [];
const cronJobs = watchedNames.length
  ? allCronJobs.filter((cj) => watchedNames.includes(cj.metadata?.name))
  : allCronJobs;

if (watchedNames.length) {
  const found = new Set(cronJobs.map((cj) => cj.metadata?.name));
  for (const name of watchedNames) {
    if (!found.has(name)) {
      // Synthetic alert when a configured CronJob is missing from the namespace.
      cronJobs.push({
        metadata: { name },
        spec: { schedule: '' },
        status: {},
        __missingFromApi: true,
      });
    }
  }
}

const jobs = (jobList.items || [])
  .filter((job) => {
    const created = Date.parse(job.metadata?.creationTimestamp || 0);
    return !Number.isNaN(created) && created >= lookbackCutoff;
  })
  .sort((a, b) => Date.parse(b.metadata.creationTimestamp) - Date.parse(a.metadata.creationTimestamp));

const alerts = [];
const healthy = [];

for (const cronJob of cronJobs) {
  const name = cronJob.metadata?.name || 'unknown';
  const schedule = cronJob.spec?.schedule || '';
  const suspend = Boolean(cronJob.spec?.suspend);
  const lastScheduleTime = cronJob.status?.lastScheduleTime || null;
  const lastSuccessfulTime = cronJob.status?.lastSuccessfulTime || null;

  if (cronJob.__missingFromApi) {
    alerts.push({
      cronJobName: name,
      issue: 'missing_cronjob',
      severity: 'critical',
      details: `CronJob '${name}' was configured in n8n but was not found in namespace '${cfg.namespace}'.`,
      schedule,
      lastScheduleTime,
      lastSuccessfulTime,
      latestJobName: null,
      latestJobState: null,
    });
    continue;
  }

  if (suspend) {
    healthy.push({
      cronJobName: name,
      status: 'suspended',
      details: 'CronJob is suspended; skipping failure/missed checks.',
    });
    continue;
  }

  const relatedJobs = jobs.filter((job) => ownerCronJobName(job) === name);
  const latestJob = relatedJobs[0] || null;
  const latest = latestJob ? jobOutcome(latestJob) : null;

  if (latest?.state === 'failed') {
    alerts.push({
      cronJobName: name,
      issue: 'job_failed',
      severity: 'critical',
      details: `Latest Job '${latestJob.metadata.name}' failed: ${latest.message}`,
      schedule,
      lastScheduleTime,
      lastSuccessfulTime,
      latestJobName: latestJob.metadata.name,
      latestJobState: latest.state,
      latestJobReason: latest.reason,
    });
    continue;
  }

  // Missed-run heuristic: if OpenShift recorded a schedule time, require a success afterward (with grace).
  if (lastScheduleTime) {
    const scheduledAt = Date.parse(lastScheduleTime);
    const graceMs = missedGraceMinutes * 60 * 1000;
    const dueBy = scheduledAt + graceMs;

    if (now > dueBy) {
      const successAfterSchedule = relatedJobs.find((job) => {
        const outcome = jobOutcome(job);
        if (outcome.state !== 'succeeded') return false;
        const finished = Date.parse(outcome.finishedAt || job.metadata.creationTimestamp);
        return finished >= scheduledAt;
      });

      const stillRunning = latest?.state === 'running_or_pending'
        && Date.parse(latestJob.metadata.creationTimestamp) >= scheduledAt;

      if (!successAfterSchedule && !stillRunning) {
        alerts.push({
          cronJobName: name,
          issue: 'missed_or_unsuccessful_run',
          severity: 'warning',
          details: `CronJob scheduled at ${lastScheduleTime} but no successful Job finished within ${missedGraceMinutes} minutes.`,
          schedule,
          lastScheduleTime,
          lastSuccessfulTime,
          latestJobName: latestJob?.metadata?.name || null,
          latestJobState: latest?.state || 'none',
        });
        continue;
      }
    }
  } else {
    // No lastScheduleTime yet — fall back to expected cadence from the cron expression.
    const intervalMinutes = estimateIntervalMinutes(schedule);
    const expectedBy = now - (intervalMinutes + missedGraceMinutes) * 60 * 1000;
    const recentSuccess = relatedJobs.find((job) => jobOutcome(job).state === 'succeeded');

    if (!recentSuccess) {
      const newestCreated = latestJob ? Date.parse(latestJob.metadata.creationTimestamp) : 0;
      if (!latestJob || newestCreated < expectedBy) {
        alerts.push({
          cronJobName: name,
          issue: 'no_recent_successful_run',
          severity: 'warning',
          details: `No successful Job found in the last ~${intervalMinutes + missedGraceMinutes} minutes for schedule '${schedule || 'unknown'}'.`,
          schedule,
          lastScheduleTime,
          lastSuccessfulTime,
          latestJobName: latestJob?.metadata?.name || null,
          latestJobState: latest?.state || 'none',
        });
        continue;
      }
    }
  }

  healthy.push({
    cronJobName: name,
    status: latest?.state || 'ok',
    details: latest
      ? `Latest Job '${latestJob.metadata.name}' is ${latest.state}.`
      : 'No recent jobs in lookback window, but no missed-run signal yet.',
    lastScheduleTime,
    lastSuccessfulTime,
  });
}

const needsAlert = alerts.length > 0;
const checkedAt = new Date().toISOString();

const subjectNames = alerts.map((a) => a.cronJobName).join(', ') || 'none';
const subject = `${cfg.alertSubjectPrefix} ${alerts.length} issue(s): ${subjectNames}`;

const lines = [];
lines.push(`OpenShift CronJob monitor found ${alerts.length} issue(s).`);
lines.push(`Cluster API: ${cfg.openshiftApiUrl}`);
lines.push(`Namespace/project: ${cfg.namespace}`);
lines.push(`Checked at: ${checkedAt}`);
lines.push('');

for (const alert of alerts) {
  lines.push(`- [${alert.severity}] ${alert.cronJobName}`);
  lines.push(`  issue: ${alert.issue}`);
  lines.push(`  details: ${alert.details}`);
  if (alert.schedule) lines.push(`  schedule: ${alert.schedule}`);
  if (alert.lastScheduleTime) lines.push(`  lastScheduleTime: ${alert.lastScheduleTime}`);
  if (alert.lastSuccessfulTime) lines.push(`  lastSuccessfulTime: ${alert.lastSuccessfulTime}`);
  if (alert.latestJobName) lines.push(`  latestJob: ${alert.latestJobName} (${alert.latestJobState})`);
  lines.push('');
}

if (healthy.length) {
  lines.push('Healthy / skipped:');
  for (const item of healthy) {
    lines.push(`- ${item.cronJobName}: ${item.details}`);
  }
}

return [
  {
    json: {
      needsAlert,
      alertCount: alerts.length,
      namespace: cfg.namespace,
      openshiftApiUrl: cfg.openshiftApiUrl,
      alertEmailTo: cfg.alertEmailTo,
      alertEmailFrom: cfg.alertEmailFrom,
      subject,
      body: lines.join('\n'),
      alerts,
      healthy,
      checkedAt,
    },
  },
];
